var FULLDICT=[];(function(){LESSONS.forEach(function(L){var st=stageOf(L.n);L.vocab.forEach(function(v){FULLDICT.push({en:v.en,so:v.so,lesson:L.n,cefr:st.cefr,stageEn:st.name.split(" — ")[0],exEn:v.exEn,exSo:v.exSo})})})})();
window.__FULLDICT_COUNT=FULLDICT.length;
