var _auditD=bilingualAudit;
bilingualAudit=function(){
 var r=_auditD();var en=0,soF=0;function chk(e,s){if(e){en++;if(s&&String(s).trim())soF++}}
 UI_PAIRS_D.forEach(function(p){chk(p[0],p[1])});
 ROLEPLAYS.forEach(function(rp){chk(rp.en,rp.so);chk(rp.npc,rp.npcSo);rp.turns.forEach(function(t){chk(t.n,t.ns);t.opts.forEach(function(o){chk(o.e,o.s);if(o.w)chk(o.e,o.w)})})});
 SOUNDS.forEach(function(sd){chk(sd.en,sd.so);chk(sd.mouthEn,sd.mouthSo);sd.pairs.forEach(function(p){chk(p[0],p[1]);chk(p[2],p[3])});(MOUTH_LABELS[sd.svg]||[]).forEach(function(l){chk(l[0],l[1])})});
 CHARTS.forEach(function(c){chk(c.en,c.so);Object.keys(c.nodes).forEach(function(k){var nd=c.nodes[k];if(nd.q)chk(nd.q,nd.qSo);if(nd.rule){chk(nd.rule,nd.ruleSo);nd.ex.forEach(function(x){chk(x[0],x[1])})}})});
 MAPTHEMES.forEach(function(t){chk(t[1],t[2])});
 return{en:r.en+en,so:r.so+soF,gaps:(r.en+en)-(r.so+soF),exEn:r.exEn,exSo:r.exSo,lessonEn:r.lessonEn,pathwayEn:0,fullDict:FULLDICT.length};
};
function wordCheck(target,out,key,onDone){
 var SR=window.SpeechRecognition||window.webkitSpeechRecognition;
 if(!SR){out.innerHTML=lng("⚠️ Browser-kani aqoonsiga hadalka ma taageero. Dhegeyso oo cod dheer ku celceli — taasi waa tababar dhab ah.","Speech check is not supported here — listen and repeat aloud instead.");if(onDone)onDone(null);return}
 try{var r=new SR();r.lang="en-GB";r.interimResults=false;
 r.onresult=function(e){var said=e.results[0][0].transcript;var tw=norm(target).split(" ").filter(Boolean);var sw=norm(said).split(" ").filter(Boolean);var hit=tw.filter(function(w){return sw.indexOf(w)>=0}).length;var full=hit===tw.length;
  if(!Array.isArray(S.skillLog))S.skillLog=[];S.skillLog.push({skill:"speaking",ok:full?1:0,date:todayStr()});
  if(!guestMode){if(full){recDay(S,key,todayStr());recDay(S,"sk:speaking|"+key,todayStr());mistakeCorrect(S,key,todayStr())}else{mistakeAdd(S,{key:key,q:"Say it in English: "+target,qSo:"Ingiriisi ku dheh: "+target,ans:target,why:target,type:"speaking",lesson:0,wordEn:"",wordSo:""})}}
  save();if(onDone)onDone({said:said,hit:hit,total:tw.length,full:full})};
 r.onerror=function(){out.textContent=lng("Mikrofoonku ma shaqeyn. Dhegeyso oo ku celceli cod dheer.","The microphone did not work. Listen and repeat aloud.");if(onDone)onDone(null)};
 r.start();out.textContent=lng("🎙️ Dhegeysanayaa... hadda dheh.","Listening... speak now.")}catch(e){out.textContent=lng("Mikrofoonku ma shaqeyn.","The microphone did not work.");if(onDone)onDone(null)}
}
var rpSel=null,rpTurn=0,rpPhase="listen",rpDone=[],rpWrong=null;
function rpState(id){ensureD();return S.stageD.rp[id]||""}
function renderRoleplay(){
 ensureD();var rp=ROLEPLAYS.filter(function(x){return x.id===rpSel})[0];if(!rp){rpSel=null;renderPractice();return}
 var sc=rp.scene?SCENES.filter(function(x){return x.id===rp.scene})[0]:null;
 var h='<button class="btn ghost" id="rpBack">'+lng('← Tababar','Practice')+'</button><h1>'+uiIcon("chat")+' '+lng(esc(rp.so),esc(rp.en))+'</h1><p class="small muted">'+lng('Tababar wadahadal oo qoraal diyaar ah — ma aha macallin AI ah, mana aha wadahadal xor ah.','Scripted conversation practice — not an AI tutor, not free conversation.')+'</p>';
 if(rp.introEn)h+='<div class="u-mb-3 card"><p class="u-mt-1 u-mb-1">'+esc(rp.introSo||"")+'<br><span class="muted">'+esc(rp.introEn)+'</span></p></div>';
 if(sc)h+='<div class="u-mb-3 scenebox">'+sc.svg+'</div>';
 if(rpTurn>=rp.turns.length){
  h+='<div class="card"><h2>'+lng('La dhammeeyay!','Finished')+'</h2><p>Jumladihii aad ku tababaratay — waxaa lagu daray kaydkaaga dib-u-eegista (Review). / Phrases you practised — added to your review pool:</p>'+rpDone.map(function(p){return '<p class="u-t-lg"><strong>'+esc(p.e)+'</strong> '+speakBtn(p.e)+'<br><span class="muted">'+esc(p.s)+'</span></p>'}).join("")+'<button class="btn" id="rpAgain">'+lng('Mar kale','Again')+'</button> <button class="btn secondary" id="rpExit">'+lng('Tababar','Practice')+'</button></div>';
  app.innerHTML=h;bindSpeak(app);
  document.getElementById("rpBack").addEventListener("click",function(){rpSel=null;render()});
  document.getElementById("rpAgain").addEventListener("click",function(){rpTurn=0;rpPhase="listen";rpDone=[];rpWrong=null;renderRoleplay()});
  document.getElementById("rpExit").addEventListener("click",function(){rpSel=null;render()});return}
 var t=rp.turns[rpTurn];
 h+='<div class="card"><p class="small muted">Khad '+ (rpTurn+1) +' / '+rp.turns.length+' · '+esc(rp.npc)+' / '+esc(rp.npcSo)+'</p>';
 h+='<div class="rpNpc"><p class="u-mt-1 u-mb-1"><strong>'+esc(rp.npc)+':</strong></p>';
 if(rpPhase==="listen"){h+='<p>'+speakBtn(t.n)+' <button class="btn secondary" id="rpPlay">'+uiIcon("play")+' '+lng('Dhegeyso','Listen')+'</button></p><p class="small muted">'+lng('Marka hore dhegeyso, kadib khadku wuu muuqdaa.','Listen first, then the line appears.')+'</p><button class="btn" id="rpReveal">'+lng('Muuji khadka','Show the line')+'</button>'}
 else{h+='<p class="u-t-lg"><strong>'+esc(t.n)+'</strong> '+speakBtn(t.n)+'<br><span class="muted">'+esc(t.ns)+'</span></p>'}
 h+='</div>';
 if(rpPhase!=="listen"){
  var correct=t.opts.filter(function(o){return o.c})[0];
  var opts=shuffle(t.opts.map(function(o,i){return{o:o,i:i}}),rpTurn*13+rpSel.length*7);
  h+='<p><strong>'+lng('Dooro jawaabtaada — ama khadka saxda ah dheh','Choose your reply — or say the correct line:')+'</strong></p><div class="opts">'+opts.map(function(x){return '<div class="optrow"><button class="opt" data-rpopt="'+x.i+'">'+esc(x.o.e)+'<br><span class="small muted">'+esc(x.o.s)+'</span></button>'+speakBtn(x.o.e)+'</div>'}).join("")+'</div>';
  h+='<p class="u-mt-3"><button class="btn secondary" id="rpMic">'+uiIcon("mic")+' '+lng('Dheh oo hubi erayada','Speak &amp; check words')+'</button> <span class="small muted" id="rpMicOut">'+lng('Hubin isbarbardhig erayo — ma aha dhibic dhawaaq.','Word-matching check — not a pronunciation score.')+'</span></p>';
  if(rpWrong)h+='<div class="feedback bad"><strong>'+uiIcon("close")+' Ma saxna. Not quite.</strong><br><strong>Sababta / Why (Soomaali):</strong> '+esc(rpWrong.w)+'<br><strong>'+esc(rpWrong.we||"")+'</strong><br><span class="small">'+lng('Jawaabta saxda ah','Correct reply:')+' <strong>'+esc(correct.e)+'</strong> — '+esc(correct.s)+'</span></div>';
 }
 h+='</div>';app.innerHTML=h;bindSpeak(app);
 document.getElementById("rpBack").addEventListener("click",function(){rpSel=null;render()});
 var pl=document.getElementById("rpPlay");if(pl)pl.addEventListener("click",function(){speak(t.n)});
 var rv=document.getElementById("rpReveal");if(rv)rv.addEventListener("click",function(){rpPhase="show";renderRoleplay()});
 app.querySelectorAll("[data-rpopt]").forEach(function(b){b.addEventListener("click",function(){var o=t.opts[+b.dataset.rpopt];
  if(o.c){rpDone.push({e:o.e,s:o.s});rpWrong=null;rpTurn++;rpPhase="listen";if(rpTurn>=rp.turns.length)finishRoleplay(rp);renderRoleplay()}
  else{if(!guestMode)mistakeAdd(S,{key:"rp|"+rp.id+"|"+rpTurn,q:"Role-play ("+rp.en+"): reply to — "+t.n,qSo:"Doorka-ciyaar ("+rp.so+"): ka jawaab — "+t.ns,opts:t.opts.map(function(x){return x.e}),ans:correct.e,why:(o.w||"")+" "+(o.we||""),type:"mcq",lesson:0,wordEn:"",wordSo:""});save();rpWrong=o;renderRoleplay()}})});
 var mic=document.getElementById("rpMic");if(mic)mic.addEventListener("click",function(){var out=document.getElementById("rpMicOut");wordCheck(correct.e,out,"rp|"+rp.id+"|"+rpTurn,function(res){if(res){out.innerHTML=lng("Waxaad tidhi","You said:")+" <strong>"+esc(res.said)+"</strong> — "+res.hit+"/"+res.total+" "+lng("eray","words.")+" ";if(res.full){out.innerHTML+=lng("🎉 Dhammaan waa sax!","All matched");rpDone.push({e:correct.e,s:correct.s});rpWrong=null;rpTurn++;rpPhase="listen";if(rpTurn>=rp.turns.length)finishRoleplay(rp);setTimeout(renderRoleplay,900)}else{out.innerHTML+=lng("Mar kale isku day, eray kasta si cad u dheh.","Try again, say each word clearly.")}}})});
}
function finishRoleplay(rp){
 ensureD();var first=S.stageD.rp[rp.id]!=="completed";S.stageD.rp[rp.id]="completed";
 rpDone.forEach(function(p){if(!S.srs.some(function(c){return c.en===p.e}))S.srs.push({en:p.e,so:p.s,box:0,due:Date.now()+86400000})});
 if(first&&!guestMode)awardBestXP("rp:"+rp.id,5);save();
}
function roleplayListHTML(){
 ensureD();
 return '<div class="u-mt-4 card"><h2>'+uiIcon("chat")+' '+lng('Doorka-ciyaar','Role-plays')+'</h2><p class="small muted">'+lng('Tababar wadahadal oo qoraal diyaar ah — ma aha macallin AI ah, mana aha wadahadal xor ah. Dhegeyso marka hore, kadib dooro jawaabta ama khadka dheh. Khaladku wuxuu aadaa safkaaga khaladaadka.','Scripted conversation practice — not an AI tutor, not free conversation. Listen first, then choose a reply or say the line. Mistakes join your mistake queue.')+'</p>'+ROLEPLAYS.map(function(rp){var st=rpState(rp.id);return '<div class="u-mb-2 lessonrow"><span class="u-grow"><strong>'+esc(rp.en)+'</strong><br><span class="small muted">'+esc(rp.so)+' · '+rp.turns.length+' '+lng('khad','lines')+'</span></span><span class="badge">'+(st==="completed"?""+uiIcon("check")+" "+lng("La dhammeeyay","Finished")+"":st==="started"?""+uiIcon("play")+" "+lng("La bilaabay","Started")+"":lng("Wali la bilaabin","Not started"))+'</span><button class="btn" data-rp="'+rp.id+'">'+lng('Bilow','Start')+'</button></div>'}).join("")+'</div>';
}
var sndSel=null;
function renderSoundStudio(){
 ensureD();var sd=SOUNDS.filter(function(x){return x.id===sndSel})[0];if(!sd){sndSel=null;renderPractice();return}
 var labels=MOUTH_LABELS[sd.svg]||[];
 var h='<button class="btn ghost" id="sndBack">'+lng('← Tababar','Practice')+'</button><h1>'+uiIcon("wave")+' '+lng(esc(sd.so),esc(sd.en))+'</h1><div class="card"><h2>'+lng('👄 Booska afka','Mouth position')+'</h2><div class="mouthwrap">'+mouthSVG(sd.svg)+'<p>'+labels.map(function(l){return '<span class="badge">'+esc(l[0])+' / '+esc(l[1])+'</span>'}).join(" ")+'</p></div><p><strong>'+esc(sd.mouthEn)+'</strong></p><p class="muted">'+esc(sd.mouthSo)+'</p></div>';
 h+='<div class="u-mt-4 card"><h2>'+uiIcon("headphones")+' '+lng('Dhegeyso','Hear it')+'</h2>'+sd.pairs.map(function(p){return '<p class="u-t-lg"><strong>'+esc(p[0])+'</strong> ('+esc(p[1].trim())+') '+speakBtn(p[0])+' &nbsp;vs&nbsp; <strong>'+esc(p[2])+'</strong> ('+esc(p[3]) +') '+speakBtn(p[2])+'</p>'}).join("");
 h+='<h3>'+lng('🧱 Qaybaha codka','Syllable blocks')+'</h3><p class="small muted">'+lng('● = cod xooggan (stress) · • = cod dabacsan','● = strong beat · • = soft beat')+'</p>'+sd.syl.map(function(s2){return '<p><strong>'+esc(s2.w)+':</strong> '+s2.b.map(function(b,i){return '<span class="sylblk">'+esc(b)+'<small class="'+(s2.d[i]?'dotB':'dotS')+'">'+(s2.d[i]?"●":"•")+'</small></span>'}).join("")+' '+speakBtn(s2.w)+'</p>'}).join("")+'</div>';
 h+='<div class="u-mt-4 card"><h2>'+uiIcon("mic")+' '+lng('Dheh','Say it')+'</h2><p class="small muted">'+lng('Hubin isbarbardhig erayo — ma aha dhibic dhawaaq, mana aha boqolkiiba (%).','Word-matching check — not a pronunciation score, never a percentage.')+'</p>'+sd.words.map(function(w){return '<p><strong>'+esc(w)+'</strong> '+speakBtn(w)+' <button class="btn secondary" data-sndsay="'+esc(w)+'">'+uiIcon("mic")+' '+lng('Dheh','Say it')+'</button> <span class="sndOut" data-out="'+esc(w)+'"></span></p>'}).join("")+'</div>';
 app.innerHTML=h;bindSpeak(app);
 document.getElementById("sndBack").addEventListener("click",function(){sndSel=null;render()});
 app.querySelectorAll("[data-sndsay]").forEach(function(b){b.addEventListener("click",function(){var w=b.dataset.sndsay;var out=app.querySelector('[data-out="'+w+'"]');
  wordCheck(w,out,"snd|"+sd.id+"|"+norm(w),function(res){ensureD();
   if(!res)return;
   if(res.full){S.stageD.snd[sd.id]=S.stageD.snd[sd.id]||{};S.stageD.snd[sd.id][norm(w)]=1;save();out.innerHTML='<span class="tlight g">'+lng('🟢 Waa isku mid','Matched')+'</span> <span class="small">“'+esc(res.said)+'”</span>'}
   else{var said=norm(res.said);var close=said&&w&&(said.charAt(0)===norm(w).charAt(0)||said.indexOf(norm(w).slice(0,3))>=0);
    out.innerHTML='<span class="tlight '+(close?"a":"r")+'">'+(close?lng("🟡 Waad ku dhawaatay — mar kale isku day","Close — try again"):lng("🔴 Wali isku mid ma aha","Not matched yet"))+'</span> <span class="small">“'+esc(res.said)+'” — dhegeyso: '+esc(w)+'</span>'}})})});
}
function soundsListHTML(){
 ensureD();
 return '<div class="u-mt-4 card"><h2>'+uiIcon("wave")+' '+lng('Istuudiyaha Dhawaaqyada','Sounds studio')+'</h2><p class="small muted">'+lng('Afkaaga sawir ku baro: booska afka, dhegeysi, kadib dheh. Hubintu waa isbarbardhig erayo — ma aha dhibic dhawaaq.','Learn sounds visually: mouth position, listening, then saying. The check is word-matching — not a pronunciation score.')+'</p>'+SOUNDS.map(function(sd){var done=S.stageD.snd[sd.id]?Object.keys(S.stageD.snd[sd.id]).length:0;return '<div class="u-mb-2 lessonrow"><span class="u-grow"><strong>'+esc(sd.en)+'</strong><br><span class="small muted">'+esc(sd.so)+'</span></span><span class="badge">'+done+' / '+sd.words.length+' '+lng('eray','words')+'</span><button class="btn" data-snd="'+sd.id+'">'+lng('Fur','Open')+'</button></div>'}).join("")+'</div>';
}
var _practiceD=renderPractice;
renderPractice=function(){
 if(rpSel){renderRoleplay();return}
 if(sndSel){renderSoundStudio();return}
 _practiceD();
 app.insertAdjacentHTML("beforeend",'<div id="stageDHub">'+roleplayListHTML()+soundsListHTML()+'<div class="u-mt-4 card"><h2>'+uiIcon("puzzle")+' '+lng('Jaantusyada naxwaha &amp; Khariidadaha','Grammar charts &amp; mind maps')+'</h2><p class="small muted">Jaantusyada go\'aanka naxwaha waxay ku jiraan Dugsiyada (Academies); khariidadaha maskaxdu waxay ku jiraan Qaamuuska. / Grammar decision charts live in Academies; mind maps live in the Dictionary.</p><button class="btn secondary" id="pdCharts">'+uiIcon("puzzle")+' '+lng('Jaantusyada','Flowcharts')+'</button> <button class="btn secondary" id="pdMaps">'+uiIcon("map")+' '+lng('Khariidadaha','Mind maps')+'</button></div></div>');
 app.querySelectorAll("[data-rp]").forEach(function(b){b.addEventListener("click",function(){ensureD();if(!S.stageD.rp[b.dataset.rp])S.stageD.rp[b.dataset.rp]="started";save();rpSel=b.dataset.rp;rpTurn=0;rpPhase="listen";rpDone=[];rpWrong=null;renderPractice()})});
 app.querySelectorAll("[data-snd]").forEach(function(b){b.addEventListener("click",function(){sndSel=b.dataset.snd;renderPractice()})});
 var pc=document.getElementById("pdCharts");if(pc)pc.addEventListener("click",function(){acadTab="charts";setNav("acad");render()});
 var pm=document.getElementById("pdMaps");if(pm)pm.addEventListener("click",function(){dictMode="maps";setNav("dict");render()});
};
var fcSel=null,fcNode="s",fcHist=[];
var _tabsD=acadTabsHTML;
acadTabsHTML=function(){return _tabsD().replace("</div>",'<button class="chipbtn '+(acadTab==="charts"?"sel":"")+'" data-atab="charts">'+uiIcon("puzzle")+' '+lng('Jaantus go\'aan','Flowcharts')+'</button></div>')};
function renderCharts(){
 ensureD();var h='<h1>'+uiIcon("cap")+' '+lng('Dugsiyo','Academies')+'</h1>'+acadTabsHTML();
 if(!fcSel){h+='<div class="card"><h2>'+uiIcon("puzzle")+' '+lng('Jaantusyada go\'aanka naxwaha','Grammar flowcharts')+'</h2><p class="muted">Su\'aalo haa/maya ah ka jawaab tallaabo tallaabo — waxaad gaari doontaa xeerka iyo laba tusaale. / Answer yes/no questions step by step — you land on the rule plus two worked examples.</p>'+CHARTS.map(function(c){return '<div class="u-mb-2 lessonrow"><span class="u-grow"><strong>'+esc(c.en)+'</strong><br><span class="small muted">'+esc(c.so)+'</span></span>'+(S.stageD.charts[c.id]?'<span class="badge">'+uiIcon("check")+'</span>':"")+'<button class="btn" data-fc="'+c.id+'">'+lng('Bilow','Start')+'</button></div>'}).join("")+'</div>';
  app.innerHTML=h;app.querySelectorAll("[data-atab]").forEach(function(b){b.addEventListener("click",function(){acadTab=b.dataset.atab;fcSel=null;renderAcad()})});
  app.querySelectorAll("[data-fc]").forEach(function(b){b.addEventListener("click",function(){fcSel=b.dataset.fc;fcNode="s";fcHist=[];renderAcad()})});return}
 var c=CHARTS.filter(function(x){return x.id===fcSel})[0];var nd=c.nodes[fcNode];
 h+='<button class="btn ghost" id="fcBack">'+lng('← Jaantusyada','Flowcharts')+'</button><div class="card"><h2>'+lng(esc(c.so),esc(c.en))+'</h2>';
 if(nd.q){h+='<div class="fcnode">'+(nd.img?'<div class="u-ta-center">'+visHTML(nd.img)+'</div>':"")+'<p class="u-t-lg"><strong>'+esc(nd.q)+'</strong></p><p class="muted">'+esc(nd.qSo)+'</p><div class="u-row u-j-center u-wrap"><button class="btn" id="fcYes">'+esc(nd.yl||lng("Haa","Yes"))+'</button><button class="btn secondary" id="fcNo">'+esc(nd.nl||lng("Maya","No"))+'</button></div>'+(fcHist.length?'<p class="u-mt-3"><button class="btn ghost" id="fcPrev">'+lng('← Dib','Back')+'</button></p>':"")+'</div>'}
 else{h+='<div class="fcrule"><h3>'+uiIcon("check")+' '+lng('Xeerka','The rule:')+' '+esc(nd.rule)+'</h3><p><strong>'+esc(nd.ruleSo)+'</strong></p><h4>'+lng('Tusaalooyin la xalliyay','Worked examples')+'</h4>'+nd.ex.map(function(x){return '<p class="u-t-lg"><strong>'+esc(x[0])+'</strong> '+speakBtn(x[0])+'<br><span class="muted">'+esc(x[1])+'</span></p>'}).join("")+'<button class="btn" id="fcAgain">'+lng('Mar kale','Start again')+'</button> <button class="btn secondary" id="fcAll">'+lng('Jaantusyada oo dhan','All charts')+'</button></div>'}
 h+='</div>';app.innerHTML=h;bindSpeak(app);
 app.querySelectorAll("[data-atab]").forEach(function(b){b.addEventListener("click",function(){acadTab=b.dataset.atab;fcSel=null;renderAcad()})});
 document.getElementById("fcBack").addEventListener("click",function(){fcSel=null;renderAcad()});
 var fy=document.getElementById("fcYes");if(fy)fy.addEventListener("click",function(){fcHist.push(fcNode);fcNode=nd.yes;if(!c.nodes[fcNode].q){ensureD();S.stageD.charts[fcSel]=1;save()}renderAcad()});
 var fn=document.getElementById("fcNo");if(fn)fn.addEventListener("click",function(){fcHist.push(fcNode);fcNode=nd.no;if(!c.nodes[fcNode].q){ensureD();S.stageD.charts[fcSel]=1;save()}renderAcad()});
 var fp=document.getElementById("fcPrev");if(fp)fp.addEventListener("click",function(){fcNode=fcHist.pop()||"s";renderAcad()});
 var fa=document.getElementById("fcAgain");if(fa)fa.addEventListener("click",function(){fcNode="s";fcHist=[];renderAcad()});
 var fl=document.getElementById("fcAll");if(fl)fl.addEventListener("click",function(){fcSel=null;renderAcad()});
}
var _acadD=renderAcad;
renderAcad=function(){if(acadTab==="charts"){renderCharts();return}_acadD()};
var _lessonD=renderLesson;
renderLesson=function(){_lessonD();if(typeof step!=="undefined"&&step===7&&!guestMode){app.insertAdjacentHTML("beforeend",'<div class="u-mt-3"><button class="btn secondary" id="lesFc">'+uiIcon("puzzle")+' '+lng('Jaantusyada go\'aanka naxwaha fur','Open grammar flowcharts')+'</button></div>');var b=document.getElementById("lesFc");if(b)b.addEventListener("click",function(){acadTab="charts";fcSel=null;setNav("acad");render()})}};
var dictMode="pic",fullQuery="",fullStage="all",fullShown=50,mapSel="home",mapWord=null;
function dictModeBar(){
 return '<div class="u-row u-wrap u-mb-4"><button class="chipbtn '+(dictMode==="pic"?"sel":"")+'" data-dmode="pic">'+uiIcon("book")+' '+lng('Qaamuuska sawirka','Picture dictionary')+'</button><button class="chipbtn '+(dictMode==="full"?"sel":"")+'" data-dmode="full">'+uiIcon("book")+' Qaamuuska buuxa / Full dictionary ('+FULLDICT.length+')</button><button class="chipbtn '+(dictMode==="maps"?"sel":"")+'" data-dmode="maps">'+uiIcon("map")+' '+lng('Khariidadaha maskaxda','Mind maps')+'</button><button class="chipbtn '+(dictMode==="wb"?"sel":"")+'" data-dmode="wb">'+uiIcon("clipboard")+' Kaydka Ereyada / Word Bank (1,000)</button></div>';
}
function wireDictBar(){app.querySelectorAll("[data-dmode]").forEach(function(b){b.addEventListener("click",function(){dictMode=b.dataset.dmode;renderDict()})})}
var _openLessonDictGuard=openLesson;
openLesson=function(n){
 if(S&&!S.profile.onboarded&&!guestMode){
  sfDialog("Marka hore soo dhawoowga dhammee","Finish the welcome first","Qaamuusku waa furan yahay — eray raadi, dhegeyso oo baro. Cashirka furkiisu wuxuu u baahan yahay inaad marka hore magacaaga geliso bogga soo dhawoowga.","The dictionary is open — search a word, listen and learn it. Opening a lesson first needs your name on the welcome screen.");
  pendingView="dict";setNav("home");render();return;
 }
 _openLessonDictGuard(n);
};
